import{_ as a,c as n,o as t,ag as s}from"./chunks/framework.Vyheyqg9.js";const h=JSON.parse('{"title":"Cost and search exercises","description":"","frontmatter":{},"headers":[],"relativePath":"practice/cs-foundations/cost-and-search.md","filePath":"practice/cs-foundations/cost-and-search.md"}'),r={name:"practice/cs-foundations/cost-and-search.md"};function o(i,e,c,d,l,p){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="cost-and-search-exercises" tabindex="-1">Cost and search exercises <a class="header-anchor" href="#cost-and-search-exercises" aria-label="Permalink to “Cost and search exercises”">​</a></h1><p><strong>Learner status: still required.</strong> Use the <a href="./#evidence-for-every-checkpoint">shared evidence requirements</a>.</p><h2 id="cs-p01-cost-and-membership" tabindex="-1"><span class="hub-section-number">1 </span>CS-P01: cost and membership <a class="header-anchor" href="#cs-p01-cost-and-membership" aria-label="Permalink to “1 CS-P01: cost and membership”">​</a></h2><p><strong>Prerequisites:</strong> <a href="./../../cs-foundations/complexity-and-cost.html">cost models</a>, dense arrays, loops and SameValueZero versus <code>Object.is</code>/<code>===</code> equality.</p><p><strong>Scope:</strong> compare repeated membership scans with one reusable Set. Use a synthetic immutable numeric dataset of at most 10,000 entries, query counts 1/10/100, and absent/early/late hits. No web app is required.</p><p><strong>Observable acceptance:</strong></p><ul><li>Both methods return identical results under a stated equality contract. Include <code>NaN</code>, ±0 and duplicates; do not compare an <code>===</code> scan against Set without accounting for NaN.</li><li>Record scan comparisons and index construction/lookup counts separately. Show an absent-query scan has n comparisons and q scans have qn; do not label Set internal hash probes as measured from one <code>.has</code> call.</li><li>Analyze expected hash-model O(n+q) time/O(n) entries versus O(nq) scans/O(1) auxiliary space, with the ECMAScript guarantee distinguished.</li><li>Mutate the dataset in a controlled second case, demonstrate a stale index, then update/rebuild under an explicit policy.</li><li>Explain geometric-resize amortization by counting copies for capacities 1/2/4/8; contrast growing by one. No need to implement an engine array.</li></ul><p><strong>Edge/failure cases:</strong> empty data/queries, stored undefined if extending the domain, all misses, index reused across changed data, and high construction cost for one query. Reject a claim that removing nesting can make required pair-output linear.</p><p><strong>Evidence:</strong> input dimensions/hit rate, exact answers, counted work, retained-entry ownership, one case favoring scanning and one amortizing indexing. If timing, warm the target runtime, repeat samples and report variation. Tiny benchmarks cannot prove growth bounds.</p><h2 id="cs-p02-lower-bound" tabindex="-1"><span class="hub-section-number">2 </span>CS-P02: lower bound <a class="header-anchor" href="#cs-p02-lower-bound" aria-label="Permalink to “2 CS-P02: lower bound”">​</a></h2><p><strong>Prerequisites:</strong> CS-P01, <a href="./../../cs-foundations/binary-search.html">binary-search invariant</a>, ascending dense finite-number contract.</p><p><strong>Scope:</strong> implement lower-bound position and first-equal lookup. Validate untrusted input separately; repeated lookups must not hide a fresh full sortedness scan.</p><p><strong>Observable acceptance:</strong></p><ul><li>Lower bound is in <code>[0,n]</code>; every earlier item is <code>&lt; target</code>, every later item is <code>≥ target</code>.</li><li>First-equal returns the earliest duplicate or −1. Compare against a simple linear oracle for exhaustive small nondecreasing arrays over <code>[-1,0,1]</code>.</li><li>Include a trace of lo/hi/mid for <code>[2,4,4,9]</code>, target 4, with a strictly shrinking interval.</li><li>Count at most <code>floor(log2(n))+1</code> comparisons for n≥1, zero for n=0; explain O(1) auxiliary space and the separate sorting/validation cost.</li></ul><p><strong>Edge/failure cases:</strong> empty/singleton, below/above range, absent between values, all equal, negative values, NaN/infinity policy, unsorted input precondition and <code>lo=mid</code> nontermination counterexample. Input is unchanged; returned indices refer to the searched ordering.</p><p><strong>Evidence:</strong> generated inputs/expected positions, failures and fixes, bound counts, loop invariant/progress proof and mutation policy. Native <code>findIndex</code> is a valid small oracle, not the implementation of the requested binary search.</p>',16)])])}const m=a(r,[["render",o]]);export{h as __pageData,m as default};
